-- CreateIndex (CONCURRENTLY)
--
-- The new conflict target for the daily tag spend upsert: the old unique key plus team_id.
-- Built before the old unique index is dropped (next migrations), so the table is never
-- without a unique index the writer can arbitrate on.
--
-- Disclaimer:
-- - CREATE INDEX CONCURRENTLY cannot run inside a transaction. This migration must stay a
--   single statement so Prisma Migrate on PostgreSQL can apply it outside a transaction.
-- - If the build is interrupted, Postgres may leave an INVALID index that must be dropped and
--   recreated.
-- - Do not edit this file after it has been applied to any database: Prisma checksums
--   migrations; add a new migration instead.
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "LiteLLM_DailyTagSpend_tag_team_id_dimensions_key" ON "LiteLLM_DailyTagSpend"("tag", "team_id", "date", "api_key", "model", "custom_llm_provider", "mcp_namespaced_tool_name", "endpoint");
